-- Acodes Phase 2: groups, media, reactions, reply/edit/delete, notifications and realtime.
alter table public.messages add column if not exists reply_to_id uuid references public.messages(id) on delete set null;
create table if not exists public.attachments (id uuid primary key default gen_random_uuid(),message_id uuid not null references public.messages(id) on delete cascade,uploader_id uuid not null references auth.users(id) on delete cascade,storage_path text not null,file_name text not null,mime_type text not null,file_size bigint not null check(file_size>0 and file_size<=10485760),created_at timestamptz not null default now());
create table if not exists public.message_reactions (id uuid primary key default gen_random_uuid(),message_id uuid not null references public.messages(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,reaction text not null check(reaction in('👍','❤️','😂','😮','😢','🔥')),created_at timestamptz not null default now(),unique(message_id,user_id,reaction));
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,actor_id uuid references auth.users(id) on delete set null,conversation_id uuid references public.conversations(id) on delete cascade,message_id uuid references public.messages(id) on delete cascade,type text not null check(type in('message','reaction','group','reply')),title text not null,body text,read_at timestamptz,created_at timestamptz not null default now());
create index if not exists attachments_message_idx on public.attachments(message_id); create index if not exists reactions_message_idx on public.message_reactions(message_id); create index if not exists notifications_user_idx on public.notifications(user_id,created_at desc);
alter table public.attachments enable row level security; alter table public.message_reactions enable row level security; alter table public.notifications enable row level security;
drop policy if exists "attachments_members_select" on public.attachments; create policy "attachments_members_select" on public.attachments for select to authenticated using(exists(select 1 from public.messages m join public.conversation_members cm on cm.conversation_id=m.conversation_id where m.id=attachments.message_id and cm.user_id=auth.uid()));
drop policy if exists "attachments_members_insert" on public.attachments; create policy "attachments_members_insert" on public.attachments for insert to authenticated with check(uploader_id=auth.uid() and exists(select 1 from public.messages m join public.conversation_members cm on cm.conversation_id=m.conversation_id where m.id=attachments.message_id and cm.user_id=auth.uid()));
drop policy if exists "attachments_own_delete" on public.attachments; create policy "attachments_own_delete" on public.attachments for delete to authenticated using(uploader_id=auth.uid());
drop policy if exists "reactions_members_select" on public.message_reactions; create policy "reactions_members_select" on public.message_reactions for select to authenticated using(exists(select 1 from public.messages m join public.conversation_members cm on cm.conversation_id=m.conversation_id where m.id=message_reactions.message_id and cm.user_id=auth.uid()));
drop policy if exists "reactions_members_insert" on public.message_reactions; create policy "reactions_members_insert" on public.message_reactions for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.messages m join public.conversation_members cm on cm.conversation_id=m.conversation_id where m.id=message_reactions.message_id and cm.user_id=auth.uid()));
drop policy if exists "reactions_own_delete" on public.message_reactions; create policy "reactions_own_delete" on public.message_reactions for delete to authenticated using(user_id=auth.uid());
drop policy if exists "notifications_own_select" on public.notifications; create policy "notifications_own_select" on public.notifications for select to authenticated using(user_id=auth.uid());
drop policy if exists "notifications_own_update" on public.notifications; create policy "notifications_own_update" on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists "notifications_own_delete" on public.notifications; create policy "notifications_own_delete" on public.notifications for delete to authenticated using(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('chat-media','chat-media',false,10485760,array['image/*','application/pdf','text/plain','text/csv','application/zip','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "acodes_chat_media_select" on storage.objects; create policy "acodes_chat_media_select" on storage.objects for select to authenticated using(bucket_id='chat-media' and exists(select 1 from public.attachments a join public.messages m on m.id=a.message_id join public.conversation_members cm on cm.conversation_id=m.conversation_id where a.storage_path=name and cm.user_id=auth.uid()));
drop policy if exists "acodes_chat_media_insert" on storage.objects; create policy "acodes_chat_media_insert" on storage.objects for insert to authenticated with check(bucket_id='chat-media' and exists(select 1 from public.conversation_members cm where cm.user_id=auth.uid() and cm.conversation_id=split_part(name,'/',1)::uuid));
drop policy if exists "acodes_chat_media_delete" on storage.objects; create policy "acodes_chat_media_delete" on storage.objects for delete to authenticated using(bucket_id='chat-media' and owner_id=auth.uid()::text);
create or replace function public.get_or_create_direct_conversation(other_user uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare me uuid:=auth.uid(); cid uuid; begin if me is null or other_user is null or me=other_user then raise exception 'Invalid users'; end if; if not exists(select 1 from auth.users where id=other_user) then raise exception 'User not found'; end if; select c.id into cid from conversations c join conversation_members a on a.conversation_id=c.id and a.user_id=me join conversation_members b on b.conversation_id=c.id and b.user_id=other_user where c.kind='direct' group by c.id having count(*)=2 limit 1; if cid is null then insert into conversations(kind,created_by) values('direct',me) returning id into cid; insert into conversation_members(conversation_id,user_id) values(cid,me),(cid,other_user); end if; return cid; end; $$; revoke all on function public.get_or_create_direct_conversation(uuid) from public,anon; grant execute on function public.get_or_create_direct_conversation(uuid) to authenticated;
create or replace function public.create_group(group_title text,member_ids uuid[]) returns uuid language plpgsql security definer set search_path=public as $$ declare me uuid:=auth.uid(); cid uuid; uid uuid; begin if me is null or length(trim(group_title))<1 or length(trim(group_title))>80 then raise exception 'Invalid group name'; end if; insert into conversations(kind,title,created_by) values('group',trim(group_title),me) returning id into cid; insert into conversation_members(conversation_id,user_id) values(cid,me); foreach uid in array coalesce(member_ids,'{}'::uuid[]) loop if uid<>me and exists(select 1 from auth.users where id=uid) then insert into conversation_members(conversation_id,user_id) values(cid,uid) on conflict do nothing; insert into notifications(user_id,actor_id,conversation_id,type,title,body) values(uid,me,cid,'group','Added to a group',trim(group_title)); end if; end loop; return cid; end; $$; revoke all on function public.create_group(text,uuid[]) from public,anon; grant execute on function public.create_group(text,uuid[]) to authenticated;
create or replace function public.manage_group_member(conversation_id_input uuid,target_user uuid,action text) returns boolean language plpgsql security definer set search_path=public as $$ declare me uuid:=auth.uid(); creator uuid; begin select created_by into creator from conversations where id=conversation_id_input and kind='group'; if creator is null or me<>creator then raise exception 'Only the group creator can manage members'; end if; if action='add' then insert into conversation_members(conversation_id,user_id) values(conversation_id_input,target_user) on conflict do nothing; elsif action='remove' then if target_user=creator then raise exception 'Creator cannot be removed'; end if; delete from conversation_members where conversation_id=conversation_id_input and user_id=target_user; else raise exception 'Invalid action'; end if; return true; end; $$; revoke all on function public.manage_group_member(uuid,uuid,text) from public,anon; grant execute on function public.manage_group_member(uuid,uuid,text) to authenticated;
create or replace function public.leave_group(conversation_id_input uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin if exists(select 1 from conversations where id=conversation_id_input and created_by=auth.uid()) then raise exception 'Group creator cannot leave'; end if; delete from conversation_members where conversation_id=conversation_id_input and user_id=auth.uid(); return true; end; $$; revoke all on function public.leave_group(uuid) from public,anon; grant execute on function public.leave_group(uuid) to authenticated;
create or replace function public.notify_new_message() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into notifications(user_id,actor_id,conversation_id,message_id,type,title,body) select cm.user_id,new.sender_id,new.conversation_id,new.id,case when new.reply_to_id is null then 'message' else 'reply' end,case when c.kind='group' then coalesce(c.title,'Group chat') else 'New message' end,left(coalesce(new.body,''),120) from conversation_members cm join conversations c on c.id=new.conversation_id where cm.conversation_id=new.conversation_id and cm.user_id<>new.sender_id; return new; end; $$; revoke all on function public.notify_new_message() from public,anon,authenticated; drop trigger if exists messages_notification_trigger on public.messages; create trigger messages_notification_trigger after insert on public.messages for each row execute function public.notify_new_message();
create or replace function public.notify_reaction() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into notifications(user_id,actor_id,conversation_id,message_id,type,title,body) select m.sender_id,new.user_id,m.conversation_id,m.id,'reaction','New reaction',new.reaction from messages m where m.id=new.message_id and m.sender_id<>new.user_id; return new; end; $$; revoke all on function public.notify_reaction() from public,anon,authenticated; drop trigger if exists reaction_notification_trigger on public.message_reactions; create trigger reaction_notification_trigger after insert on public.message_reactions for each row execute function public.notify_reaction();
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='message_reactions') then alter publication supabase_realtime add table public.message_reactions; end if; if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='notifications') then alter publication supabase_realtime add table public.notifications; end if; if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='attachments') then alter publication supabase_realtime add table public.attachments; end if; if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='conversation_members') then alter publication supabase_realtime add table public.conversation_members; end if; end $$;
